import json

def calculator(**kwargs):
    if kwargs['operation'] == 'add':
        return json.loads('{"tool": "add", "arguments": {"a": 1, "b": 2}}')
    elif kwargs['operation'] =='multiply':
        return json.loads('{"tool": "multiply", "arguments": {"a": 1, "b": 2}}')
    else:
        return json.loads('{"tool": "error", "arguments": {"error": "unknown operation"}}')

def lookup(**kwargs):
    return json.loads('{"tool": "lookup", "arguments": {"query": "foo"}}')

def abstain(**kwargs):
    return json.loads('{"tool": "abstain", "arguments": {}}')

def python(**kwargs):
    return json.loads('{"tool": "python", "arguments": {"code": "print(1 + 2)"}}')
